# Python - minimal pluggable provider
class BaseCredentialProvider:
    def attach(self, headers):
        raise NotImplementedError

    async def refresh(self):
        """Optional: refresh short-lived token proactively. Return True if refreshed."""
        return False

# Default env provider
class EnvProvider(BaseCredentialProvider):
    def __init__(self, env_var='REDWOOD_API_KEY'):
        self.env_var = env_var
    def attach(self, headers):
        key = os.getenv(self.env_var)
        if key:
            headers['Authorization'] = f'Bearer {key}'

# Streaming client pseudocode
class StreamingClient:
    def __init__(self, provider: BaseCredentialProvider, grace_window=60):
        self.provider = provider
        self.grace_window = grace_window

    async def start_stream(self, resume_token=None):
        headers = {}
        self.provider.attach(headers)
        stream = await open_stream(headers, resume_token)
        try:
            async for msg in stream:
                process(msg)
        except AuthError as e:
            # attempt refresh and resume
            refreshed = await self.provider.refresh()
            if refreshed:
                headers = {}
                self.provider.attach(headers)
                stream = await open_stream(headers, resume_token)
                async for msg in stream:
                    process(msg)
            else:
                raise

// TypeScript - example credential adapter and streaming reconnect
export interface CredentialProvider {
  attach(headers: Record<string,string>): void
  refresh?(): Promise<boolean>
}

export class EnvProvider implements CredentialProvider {
  constructor(private envKey = 'REDWOOD_API_KEY'){}
  attach(headers: Record<string,string>){
    const k = process.env[this.envKey]
    if(k) headers['authorization'] = `Bearer ${k}`
  }
}

// streaming reconnect flow (pseudocode)
async function startStream(provider: CredentialProvider, resumeToken?: string){
  const headers: Record<string,string> = {}
  provider.attach(headers)
  const stream = await openStream(headers, resumeToken)
  try{
    for await (const msg of stream) handle(msg)
  }catch(e){
    if(isAuthError(e) && provider.refresh){
      const ok = await provider.refresh()
      if(ok){
        const headers2: Record<string,string> = {}
        provider.attach(headers2)
        const newStream = await openStream(headers2, resumeToken)
        for await (const msg of newStream) handle(msg)
      }else{
        throw e
      }
    }else{
      throw e
    }
  }
}

// Go - example: provider interface + streaming reconnect (simplified)
package sdk

import (
    "context"
    "time"
)

type CredentialProvider interface {
    Attach(headers map[string]string)
    Refresh(ctx context.Context) (bool, error) // refresh if supported
}

func StartStream(ctx context.Context, provider CredentialProvider, resumeToken string) error {
    headers := map[string]string{}
    provider.Attach(headers)
    stream, err := openStream(ctx, headers, resumeToken)
    if err != nil {
        return err
    }
    for {
        msg, err := stream.Recv()
        if err == AuthError {
            ok, rerr := provider.Refresh(ctx)
            if rerr != nil || !ok {
                return err
            }
            headers := map[string]string{}
            provider.Attach(headers)
            stream, err = openStream(ctx, headers, resumeToken)
            if err != nil {
                return err
            }
            continue
        }
        if err != nil {
            return err
        }
        handle(msg)
    }
}
